using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows.Forms;using System.Windows.Forms.Integration;using System.Windows.Media.Media3D;
namespace GearLab {
 public sealed class WaveParameters {
  public int Ratio=50;public double Module=.6,CupDepth=25,Thickness=8,Wall=.8,RingWall=4,Bore=5,OutputBore=8,Clearance=.15,BearingWall=1.5;
  public double InputTorque=.35,InputRpm=60,Efficiency=.7,LoadTorque=5;
  public int FlexTeeth{get{return 2*Ratio;}}public int RingTeeth{get{return FlexTeeth+2;}}
  public double OutputRpm{get{return -InputRpm/Ratio;}}public double OutputTorque{get{return InputTorque*Ratio*Efficiency;}}
  public double InputPower{get{return InputTorque*InputRpm*Math.PI/30;}}public double RequiredTorque{get{return LoadTorque/(Ratio*Efficiency);}}
  public void Validate(){if(Ratio<20||Ratio>120||!Finite(InputTorque)||InputTorque<0||!Finite(InputRpm)||InputRpm<0||!Finite(Efficiency)||Efficiency<=0||Efficiency>1||!Finite(LoadTorque)||LoadTorque<0)throw new Exception("Передача 20–120; момент, обороты и нагрузка ≥ 0; КПД 0–1, исключая 0.");}
  static bool Finite(double n){return !double.IsNaN(n)&&!double.IsInfinity(n);}
  public CADFeature Feature(double phase=0){Validate();return new CADFeature{Kind="wave",Name="Волновой редуктор "+Ratio+":1",Values=new Dictionary<string,string>{{"Ratio",Ratio.ToString()},{"Module",Engine.N(Module)},{"CupDepth",Engine.N(CupDepth)},{"Thickness",Engine.N(Thickness)},{"Wall",Engine.N(Wall)},{"RingWall",Engine.N(RingWall)},{"Bore",Engine.N(Bore)},{"OutputBore",Engine.N(OutputBore)},{"Clearance",Engine.N(Clearance)},{"BearingWall",Engine.N(BearingWall)},{"Phase",Engine.N(phase)}}};}
  public CADDocument Document(double phase=0){var doc=new CADDocument{Name="Волновой редуктор "+Ratio+":1"};var f=Feature(phase);doc.Features.Add(f);ApplyMaterials(doc,f);return doc;}
  public static void ApplyMaterials(CADDocument doc,CADFeature f){doc.Materials[f.Id+"_ring"]=new CADMaterial{Name="Сталь",Density=7850,Color=Color.FromArgb(80,90,103).ToArgb()};doc.Materials[f.Id+"_flex"]=new CADMaterial{Name="Сталь",Density=7850,Color=Color.FromArgb(225,123,52).ToArgb()};doc.Materials[f.Id+"_generator"]=new CADMaterial{Name="Сталь",Density=7850,Color=Color.FromArgb(65,135,189).ToArgb()};doc.Materials[f.Id+"_bearing"]=new CADMaterial{Name="Сталь",Density=7850,Color=Color.Silver.ToArgb()};}
 }
 public static class WaveMotion {
  // Prescribed visualization of an elastic cup. No contact or elasticity solver is implied.
  public static SceneMesh Deform(SceneMesh original,WaveParameters p,double phase){var points=new Point3D[original.Points.Length];var normals=new Vector3D[points.Length];double floor=Math.Max(1.5,2*p.Wall),depth=p.CupDepth-floor,axis=phase+phase/p.Ratio,c=Math.Cos(axis),s=Math.Sin(axis);for(int i=0;i<points.Length;i++){var q=original.Points[i];double f=Math.Max(0,Math.Min(1,(q.Z+depth)/depth)),k=f/p.Ratio;double a=1+k,b=1-k;double x=q.X/a,y=q.Y/b;double u=c*x+s*y,v=-s*x+c*y;points[i]=new Point3D(c*a*u-s*b*v,s*a*u+c*b*v,q.Z);}for(int j=0;j<original.Indices.Length;j+=3){int a=original.Indices[j],b=original.Indices[j+1],d=original.Indices[j+2];var n=Vector3D.CrossProduct(points[b]-points[a],points[d]-points[a]);if(n.LengthSquared>1e-20)n.Normalize();normals[a]+=n;normals[b]+=n;normals[d]+=n;}for(int i=0;i<normals.Length;i++)if(normals[i].LengthSquared>1e-20)normals[i].Normalize();return new SceneMesh{Points=points,Normals=normals,Indices=original.Indices};}
 }
 public sealed partial class WaveReducerForm:Form {
  internal bool TestReady{get{return model!=null&&scene.Ready&&!busy;}}
  readonly CADKernel kernel=new CADKernel();readonly WpfScene scene=new WpfScene();readonly ElementHost host=new ElementHost();readonly Timer timer=new Timer();readonly System.Diagnostics.Stopwatch watch=new System.Diagnostics.Stopwatch();readonly Label metrics=new Label(),status=new Label();readonly CADValueEditor editor;readonly FlowLayoutPanel actions=new FlowLayoutPanel();readonly NumericUpDown speed=new NumericUpDown();Func<CADFeature,Task<bool>> insert;CADKernel shared;Action returnToTarget;bool hasTargetButton;WaveParameters model;CADDocument document;bool busy,playing,closing,disposed,inserting;double phase,last;
  public WaveReducerForm():this(null,null){}
  public WaveReducerForm(CADKernel sharedKernel,Func<CADFeature,Task<bool>> insertFeature){shared=sharedKernel;insert=insertFeature;Text="GearLab 5.4 · Волновой редуктор";Font=new Font("Segoe UI",10);Size=new Size(1350,900);MinimumSize=new Size(1100,760);StartPosition=FormStartPosition.CenterParent;var split=new SplitContainer{Dock=DockStyle.Fill,Size=new Size(1300,820),SplitterDistance=360,FixedPanel=FixedPanel.Panel1,Panel1MinSize=330,Panel2MinSize=700};var left=new Panel{Dock=DockStyle.Fill,AutoScroll=true};split.Panel1.Controls.Add(left);var fields=new Dictionary<string,string>{{"Ratio","50"},{"Module","0.6"},{"CupDepth","25"},{"Thickness","8"},{"Wall","0.8"},{"RingWall","4"},{"Bore","5"},{"OutputBore","8"},{"Clearance","0.15"},{"BearingWall","1.5"},{"InputTorque","0.35"},{"InputRpm","60"},{"Efficiency","0.7"},{"LoadTorque","5"}};editor=new CADValueEditor(fields){Dock=DockStyle.Top,Height=fields.Count*38+10};var presets=new FlowLayoutPanel{Dock=DockStyle.Top,Height=45};foreach(int ratio in new[]{50,80,100}){int r=ratio;var button=new Button{Text=r+":1",Width=90,Height=32};button.Click+=(s,e)=>{if(busy)return;editor.SetValue("Ratio",r.ToString());Build();};presets.Controls.Add(button);}metrics.Dock=DockStyle.Top;metrics.Height=175;metrics.Padding=new Padding(8);metrics.Text="Рассчитайте модель.";left.Controls.Add(metrics);left.Controls.Add(editor);left.Controls.Add(presets);host.Dock=DockStyle.Fill;host.Child=scene.Root;split.Panel2.Controls.Add(host);actions.Dock=DockStyle.Bottom;actions.Height=90;Add("Построить",Build);Add("▶ / ❚❚",()=>{if(model==null)return;playing=!playing;last=watch.Elapsed.TotalSeconds;});Add("Нулевое положение",()=>{playing=false;phase=0;scene.UpdatePose(0);});Add("Разнести детали",()=>{scene.Exploded=!scene.Exploded;scene.UpdatePose(phase);});Add("Сечение",()=>{scene.Axis=scene.Axis<0?0:-1;scene.Coordinate=0;scene.UpdatePose(phase,true);});Add("В CAD Studio",OpenCAD);Add("Сохранить проект",Save);Add("STEP",()=>Export("export_step"));Add("STL",()=>Export("export_stl"));if(insert!=null){Add("✓ Вставить в модель",Insert);hasTargetButton=true;}actions.Controls.Add(new Label{Text="Скорость просмотра ×",AutoSize=true,Padding=new Padding(3,8,0,0)});speed.DecimalPlaces=2;speed.Minimum=.01m;speed.Maximum=10;speed.Value=.25m;speed.Width=70;actions.Controls.Add(speed);Add("Отмена расчёта",()=>{if(inserting&&shared!=null)shared.Cancel();else kernel.Cancel();});status.Dock=DockStyle.Bottom;status.Height=64;status.Padding=new Padding(8);status.Text="Жёсткий венец закреплён, генератор — вход, чашка — выход.\nЗаданная деформация; упругость, контакт зубьев и допустимый момент не рассчитываются.";Controls.Add(split);Controls.Add(actions);Controls.Add(status);timer.Interval=100;timer.Tick+=(s,e)=>{double now=watch.Elapsed.TotalSeconds,dt=Math.Min(.2,now-last);last=now;if(playing&&model!=null&&!busy){phase+=dt*model.InputRpm*Math.PI/30*(double)speed.Value;scene.UpdatePose(phase);}};watch.Start();timer.Start();Shown+=(s,e)=>Build();FormClosing+=(s,e)=>{if(busy&&!closing){MessageBox.Show(this,"Дождитесь построения или нажмите «Отмена расчёта».");e.Cancel=true;}};}
  internal void ConfigureTarget(CADKernel sharedKernel,Func<CADFeature,Task<bool>> callback,Action returnTo){shared=sharedKernel;insert=callback;returnToTarget=returnTo;if(!hasTargetButton){Add("✓ Вставить в CAD-модель",Insert);hasTargetButton=true;}}
  void Add(string text,Action action){var b=new Button{Text=text,AutoSize=true,Height=32};b.Click+=(s,e)=>action();actions.Controls.Add(b);}
  WaveParameters Read(){var v=editor.Values();Func<string,double> n=k=>CADExpression.Evaluate(v[k],null);double ratio=n("Ratio");if(ratio!=Math.Round(ratio))throw new Exception("Передаточное число должно быть целым.");var p=new WaveParameters{Ratio=(int)ratio,Module=n("Module"),CupDepth=n("CupDepth"),Thickness=n("Thickness"),Wall=n("Wall"),RingWall=n("RingWall"),Bore=n("Bore"),OutputBore=n("OutputBore"),Clearance=n("Clearance"),BearingWall=n("BearingWall"),InputTorque=n("InputTorque"),InputRpm=n("InputRpm"),Efficiency=n("Efficiency"),LoadTorque=n("LoadTorque")};p.Validate();return p;}
  async void Build(){if(busy)return;busy=true;playing=false;status.Text="Построение точных CAD-тел…";try{var p=Read();var doc=p.Document();var result=await Task.Factory.StartNew(()=>kernel.Run(doc));if(IsDisposed)return;var assembly=result.Assembly(doc);model=p;document=doc;phase=0;scene.SetResult(new Result{P=new Parameters{Kind=4},Actual=p.Ratio,Model=assembly,Wave=p},true);metrics.Text="Зубья чашки / венца: "+p.FlexTeeth+" / "+p.RingTeeth+"\nПередача: −"+p.Ratio+":1 · выход в обратную сторону\nВыход: "+Engine.F(p.OutputRpm)+" об/мин · "+Engine.F(p.OutputTorque)+" Н·м\nВходная мощность: "+Engine.F(p.InputPower)+" Вт\nДля нагрузки "+Engine.F(p.LoadTorque)+" Н·м нужно на входе "+Engine.F(p.RequiredTorque)+" Н·м\n"+(p.OutputTorque>=p.LoadTorque?"Заданный входной момент покрывает нагрузку при указанном КПД.":"Заданного входного момента недостаточно.");status.Text="Готово. КПД задан пользователем; момент на оборотах должен быть взят из характеристики мотора.\nГеометрическая концепция. Упругость, контакт, ресурс и прочность чашки требуют отдельного расчёта.";}catch(Exception ex){Error(ex);}finally{busy=false;}}
  void Error(Exception ex){status.ForeColor=Color.Firebrick;status.Text="Построение не выполнено: "+ex.GetBaseException().Message;}
  CADDocument Current(){var d=document.Clone();d.Features[0].Values["Phase"]=Engine.N(phase*180/Math.PI);return d;}
  void OpenCAD(){if(busy||document==null)return;playing=false;new CADStudioForm(Current(),null).ShowWorkspace(this);}
  void Save(){if(busy||document==null)return;playing=false;using(var d=new SaveFileDialog{Filter="CAD-проект с параметрами|*.cad.json",FileName=document.Name+".cad.json"})if(d.ShowDialog(this)==DialogResult.OK)try{Current().Save(d.FileName);}catch(Exception ex){Error(ex);}}
  async void Export(string mode){if(busy||document==null)return;playing=false;using(var d=new SaveFileDialog{Filter=mode=="export_step"?"STEP|*.step":"STL|*.stl",FileName=document.Name+(mode=="export_step"?".step":".stl")})if(d.ShowDialog(this)==DialogResult.OK){busy=true;try{var doc=Current();await Task.Factory.StartNew(()=>kernel.Run(doc,mode,d.FileName));status.Text="Сохранено: "+d.FileName;}catch(Exception ex){Error(ex);}finally{busy=false;}}}
  async void Insert(){if(busy||document==null||insert==null)return;playing=false;busy=true;inserting=true;status.Text="Вставка CAD-тел в документ…";try{var f=Current().Features[0];if(await insert(f)){if(returnToTarget!=null){status.Text="Редуктор добавлен в CAD-модель.";returnToTarget();}else{closing=true;busy=false;Close();}}}catch(Exception ex){Error(ex);}finally{busy=false;inserting=false;}}
  protected override void Dispose(bool disposing){if(disposing&&!disposed){disposed=true;timer.Dispose();kernel.Dispose();scene.Dispose();host.Child=null;}base.Dispose(disposing);}
 }
